/**
 * Unit tests for org.apache.commons.lang.Entities#escape
 */
public class Entities_escape_TriageGen0Test {

    private Entities entities;
    private StringWriter writer;

    @Before
    public void setUp() {
        entities = new Entities();
        writer = new StringWriter();
    }



    @Test
    public void testEscape_WithNamedEntities() throws IOException {
        // Tests the branch where entityName is not null
        // Note: Standard HTML entities like '<' (lt), '>' (gt), '&' (amp), '"' (quot) 
        // are typically handled by Entities class.
        String input = "<&>";
        entities.escape(writer, input);
        // Expected output depends on internal entityName implementation, 
        // but following the logic: &lt;&amp;&gt;
        String result = writer.toString();
        Assert.assertTrue(result.contains("&lt;"));
        Assert.assertTrue(result.contains("&amp;"));
        Assert.assertTrue(result.contains("&gt;"));
    }












}

