import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.Entities#escape
 */
public class Entities_escape_TriageGen0Test {

    private Entities entities;
    private StringWriter writer;

    @Before
    public void setUp() {
        entities = new Entities();
        writer = new StringWriter();
    }







    @Test
    public void testEscape_MixedContent() throws IOException {
        // Tests combination of all branches
        // 1. Named entity (<)
        // 2. Standard ASCII (a)
        // 3. High ASCII (\u00A9 - Copyright symbol)
        String input = "<a\u00A9";
        entities.escape(writer, input);
        String result = writer.toString();

        // Check if named entity is used
        Assert.assertTrue(result.startsWith("&lt;"));
        // Check if standard char is used
        Assert.assertTrue(result.contains("a"));
        // Check if numeric entity is used for high ASCII
        Assert.assertTrue(result.contains("&#169;"));
    }








}

